// 设置路由守卫，在进页面之前，判断有token，才进入页面，否则返回登录页面
router.beforeEach((to, from, next) => {
  // console.log(!store.getters.getToken);
  if (to.path != '/login') {
    // 定义可以在没有 token 的情况下访问的页面
    const publicPages = ['/activatebywjj', '/activate2'];
    if (!store.getters.getToken && !publicPages.includes(to.path)) {
      // if(store.state.version == 'login'){
      next('/login')
      // }else{
      // next()
      // }
    } else {
      if (from.path == '/sssp') {
        // 在离开特定页面时执行操作
        // axios.post($url.url_7000 + '/stop_all_camera')
        window.I_DestroyPlugin()
      }
      // console.log('2');
      next()
    }
  } else {
    console.log('3');
    if (from.path == '/sssp') {
      // 在离开特定页面时执行操作
      // axios.post($url.url_7000 + '/stop_all_camera')
      window.I_DestroyPlugin()
    }
    next();
  }
})

