// src/store/index.js
import Vue from 'vue';
import Vuex from 'vuex';
// 引入vuex持久化方法createPersistedState
import createPersistedState from 'vuex-persistedstate'


Vue.use(Vuex);

const store = new Vuex.Store({
  state: {
    // 在这里定义你的状态
    version: '',//版本信息
    menuData: [],//菜单信息
    token: '',//储存token
    userId: "",// 存储user_id
    user_role_id: "",// 存储user_role_id
  },
  mutations: {
    // 在这里定义修改状态的方法 (同步)
    // 修改token，并将token存入localStorage
    setToken(state, token) {
      state.token = token;
      localStorage.setItem('token', token);
      console.log('store、localstorage保存token成功！');
    },
    delToken(state) {
      state.token = "";
      localStorage.removeItem("token");
    },
    // 可选
    setUserInfo(state, userId) {
      state.userId = userId;
      localStorage.setItem('userId', userId);
    },
    // 可选
    setUserInfos(state, userId) {
      state.user_role_id = userId;
      localStorage.setItem('user_role_id', userId);
    },
    // 可选
    userRoleName(state, userId) {
      state.userRoleName = userId;
      localStorage.setItem('userRoleName', userId);
    }
    
  },
  actions: {
    // 在这里定义触发状态变更的方法 (可以是异步的)
  },
  getters: {
    // 在这里定义从状态中获取数据的方法
    getToken(state) {
      return state.token || localStorage.getItem("token") || "";
    }
  },
  plugins: [
    // veux持久化配置
    createPersistedState({
      key: 'vuex_data',
      paths: ['lock']
    })
  ],
});

export default store;